import { readFile, writeFile } from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

// The gallery must show the current shared artwork, including its material layers.
const check = spawnSync(process.execPath, [fileURLToPath(new URL('../../scripts/generate-brand.mjs', import.meta.url)), '--check'], { stdio: 'inherit' });
if (check.error || check.status !== 0) throw new Error('Generate the shared brand assets before rebuilding the gallery.');

// Embed each vector once. Prefix its definitions and their references together:
// removing source IDs would break the app icon's gradients and reused shadow paths.
async function loadBrandSymbol(filename, id) {
 const source = await readFile(new URL(`../../Resources/Brand/${filename}`, import.meta.url), 'utf8');
 const viewBox = source.match(/<svg\b[^>]*\bviewBox="([^"]+)"/)?.[1];
 let artwork = source.replace(/^[\s\S]*?<svg\b[^>]*>/, '').replace(/<\/svg>[\s\S]*$/, '')
  .replace(/<(title|desc|metadata)\b[^>]*>[\s\S]*?<\/\1>/g, '')
  .replace(/\saria-labelledby="[^"]*"/g, '').trim();
 const bounds = viewBox?.trim().split(/\s+/).map(Number);
 if (!bounds || bounds.length !== 4 || bounds.some(value => !Number.isFinite(value)) || bounds[2] <= 0 || bounds[3] <= 0 || !artwork.includes('<path')) {
  throw new Error(`Invalid brand vector: ${filename}`);
 }
 const ids = new Map();
 for (const match of artwork.matchAll(/\sid="([^"]+)"/g)) {
  if (ids.has(match[1])) throw new Error(`Duplicate SVG definition in ${filename}: ${match[1]}`);
  ids.set(match[1], `${id}-${match[1]}`);
 }
 const reference = original => {
  if (!ids.has(original)) throw new Error(`Unresolved SVG definition in ${filename}: ${original}`);
  return ids.get(original);
 };
 artwork = artwork.replace(/\sid="([^"]+)"/g, (_, original) => ` id="${reference(original)}"`)
  .replace(/url\(\s*(['"]?)#([^)'"\s]+)\1\s*\)/g, (_, quote, original) => `url(#${reference(original)})`)
  .replace(/\b((?:xlink:)?href)="([^"]+)"/g, (_, attribute, target) => {
   if (!target.startsWith('#')) throw new Error(`External resource in brand vector: ${filename}`);
   return `${attribute}="#${reference(target.slice(1))}"`;
  });
 return { viewBox, symbol: `<symbol id="${id}" viewBox="${viewBox}" preserveAspectRatio="xMidYMid meet">${artwork}</symbol>` };
}
const [markSource, wordmarkSource, appIconSource, brandSource] = await Promise.all([
 loadBrandSymbol('inkflow.svg', 'gallery-inkflow'),
 loadBrandSymbol('wordmark.svg', 'gallery-wordmark'),
 loadBrandSymbol('generated/app-icon.svg', 'gallery-app-icon'),
 readFile(new URL('../../Resources/Brand/brand.json', import.meta.url), 'utf8'),
]);
const brand = JSON.parse(brandSource);
for (const name of ['ink', 'ivory', 'accent', 'darkAccent', 'tint']) {
 if (!/^#[\dA-F]{6}$/i.test(brand.colors?.[name] ?? '')) throw new Error(`Missing or invalid gallery palette token: ${name}`);
}
const [, , markWidth, markHeight] = markSource.viewBox.split(/\s+/).map(Number);
const markAspectRatio = markWidth / markHeight;
const [, , wordmarkWidth, wordmarkHeight] = wordmarkSource.viewBox.split(/\s+/).map(Number);
const wordmarkAspectRatio = wordmarkWidth / wordmarkHeight;
const brandDefinitions = `<svg xmlns="http://www.w3.org/2000/svg" class="brand-definitions" width="0" height="0" aria-hidden="true"><defs>${markSource.symbol}${wordmarkSource.symbol}${appIconSource.symbol}</defs></svg>`;
const mark = `<svg class="mark" viewBox="${markSource.viewBox}" fill="currentColor" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><use href="#gallery-inkflow"/></svg>`;
const wordmark = `<svg class="wordmark" viewBox="${wordmarkSource.viewBox}" fill="currentColor" role="img" aria-label="DictaDuo"><use href="#gallery-wordmark"/></svg>`;
const appIcon = `<svg class="app-icon" viewBox="${appIconSource.viewBox}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><use href="#gallery-app-icon"/></svg>`;

