 const isTray=d.cls==='tray';const inner=contentFor(page,mode);
 return `<div class="mock-scroll"><div class="app-window ${d.cls} ${extra}" data-app="${d.id}" aria-label="${d.name}, ${page} mockup"><div class="window-chrome"><span class="window-app-icon">${appIcon}</span><span>DictaDuo${isTray?'':' · '+page}</span><span class="window-controls"><i>−</i><i>□</i><i>×</i></span></div><div class="app-layout"><aside class="app-sidebar"><div class="brand"><span class="brand-icon">${appIcon}</span>${wordmark}</div>${nav(page==='Appearance'?'This computer':page)}<div class="sidebar-bottom">${dot('Server online')}<small>Home server</small></div></aside><div class="main-stack"><div class="tab-brand"><span class="brand">${mark}${wordmark}</span>${nav(page)}</div><main class="app-main">${isTray?`<div class="tray-nav">${mark}${wordmark}<span class="spacer"></span>${icon('more')}</div>`:''}${d.cls==='workspace'?`<div class="workspace-content">${inner}</div><aside class="source-inspector"><h4>Audio path</h4><div class="inspector-source">${icon('mic')}<strong>DJI Mic Mini</strong><small>Receiver on Home server</small>${tag('Ready','positive')}</div><div class="inspector-line"></div><div class="inspector-source">${icon('computer')}<strong>This computer</strong><small>Text goes to your cursor</small></div><hr><small>Next fallback</small><p>AirPods Pro 3</p><span class="text-action">Edit priority</span></aside>`:inner}</main></div></div></div></div>`;
